CREATE OR REPLACE FUNCTION public.mark_pause_investigated(p_pause_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE v_uid uuid := auth.uid(); v_profile uuid; v_notes text; v_row public.instance_pauses; v_ja boolean; BEGIN IF v_uid IS NULL OR NOT public.is_admin_or_supervisor(v_uid) THEN RAISE EXCEPTION 'sem_permissao_para_investigar_pausa' USING ERRCODE = '42501'; END IF; IF p_pause_id IS NULL THEN RAISE EXCEPTION 'pausa_invalida' USING ERRCODE = '22023'; END IF; v_profile := public.get_profile_id_for_user(v_uid); IF v_profile IS NULL THEN RAISE EXCEPTION 'perfil_nao_encontrado' USING ERRCODE = '42501'; END IF; IF p_notes IS NOT NULL THEN v_notes := btrim(p_notes); IF v_notes = '' THEN v_notes := NULL; END IF; IF v_notes IS NOT NULL THEN IF char_length(v_notes) > 1000 THEN RAISE EXCEPTION 'notas_acima_do_limite' USING ERRCODE = '22023'; END IF; IF v_notes ~ '[<>]' THEN RAISE EXCEPTION 'notas_com_html' USING ERRCODE = '22023'; END IF; END IF; END IF; SELECT * INTO v_row FROM public.instance_pauses WHERE id = p_pause_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'pausa_nao_encontrada' USING ERRCODE = 'P0002'; END IF; v_ja := v_row.investigated_at IS NOT NULL; UPDATE public.instance_pauses SET investigated_at = COALESCE(investigated_at, now()), investigated_by = COALESCE(investigated_by, v_profile), investigation_notes = COALESCE(v_notes, investigation_notes) WHERE id = p_pause_id RETURNING * INTO v_row; INSERT INTO public.audit_logs (user_id, action, entity_type, entity_id, details) VALUES (v_uid, 'instance_pause_investigated', 'instance_pause', v_row.id, jsonb_build_object('instance', v_row.instance, 'ja_investigada', v_ja, 'com_notas', v_row.investigation_notes IS NOT NULL)); RETURN jsonb_build_object('id', v_row.id, 'instance', v_row.instance, 'investigated_at', v_row.investigated_at, 'investigated_by', v_row.investigated_by, 'investigation_notes', v_row.investigation_notes, 'ja_investigada', v_ja); END $function$
